<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Request,Response};use App\Repositories\{AcademicRepository,EmployeeRepository,PakistanErpRepository,SettingsRepository,StudentRepository};use App\Support\{Flash,SecureAttachment};
final class NotesController extends AdminPageController{
private function i():int{return(int)(new SettingsRepository($this->app->database()))->institute()['id'];}private function r():PakistanErpRepository{return new PakistanErpRepository($this->app->database());}
public function index(Request$q):Response{return$this->view('notes/index',['pageTitle'=>'Student Resources','activeMenu'=>'homework','activeSubmenu'=>'notes','institute'=>(new SettingsRepository($this->app->database()))->institute(),'notes'=>$this->r()->notes($this->i(),(int)$q->query('class',0),(int)$q->query('subject',0)),'classes'=>(new AcademicRepository($this->app->database()))->withSubjects($this->i()),'students'=>(new StudentRepository($this->app->database()))->basicList($this->i(),'',null),'teachers'=>(new EmployeeRepository($this->app->database()))->all($this->i(),'',true)]);}
public function store(Request$q):Response{try{$path=SecureAttachment::store($q->file('attachment'),'notes');$this->r()->saveNote($this->i(),['audience_type'=>(string)$q->input('audience_type','class'),'class_ids'=>(array)$q->input('class_ids',[]),'class_id'=>(int)$q->input('class_id')?:null,'subject_id'=>(int)$q->input('subject_id')?:null,'student_id'=>(int)$q->input('student_id')?:null,'teacher_id'=>(int)$q->input('teacher_id')?:null,'chapter'=>trim((string)$q->input('chapter'))?:null,'title'=>trim((string)$q->input('title')),'description'=>trim((string)$q->input('description'))?:null,'attachment_path'=>$path,'external_url'=>trim((string)$q->input('external_url'))?:null,'publish_date'=>(string)$q->input('publish_date'),'status'=>(string)$q->input('status'),'created_by'=>(int)user()['id']]);Flash::add('success','Student resource saved.');}catch(\DomainException$e){Flash::add('error',$e->getMessage());}return Response::redirect(url('/admin/notes'));}
public function delete(Request$q):Response{$path=$this->r()->deleteNote((int)$q->route('id'),$this->i());if($path&&is_file(BASE_PATH.'/'.$path))unlink(BASE_PATH.'/'.$path);return Response::redirect(url('/admin/notes'));}
}
